# PTX source for fp16 matrix‑vector multiplication (A[M,K] @ B[K,1] = C[M,1])
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry matvec_kernel (
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K
)
{
    // ----------- thread/block indices ----------
    .reg .pred   %p;
    .reg .b32    %tid, %bid, %lane;
    .reg .b64    %A, %B, %C;
    .reg .b32    %M, %K;
    .reg .b64    %row_offset, %a_addr, %b_addr, %c_addr;
    .reg .f32    %sum, %a_f32, %b_f32;
    .reg .f16    %a_f16, %b_f16;
    .reg .b32    %col;

    // load parameters
    ld.param.u64    %A, [A_ptr];
    ld.param.u64    %B, [B_ptr];
    ld.param.u64    %C, [C_ptr];
    ld.param.u32    %M, [M];
    ld.param.u32    %K, [K];

    // thread and block ids
    mov.u32 %tid, %tid.x;
    mov.u32 %bid, %ctaid.x;

    // if (bid >= M) exit
    setp.ge.u32 %p, %bid, %M;
    @%p bra DONE;

    // row offset = bid * K
    mul.wide.u32 %row_offset, %bid, %K;          // 64‑bit offset

    // initialize accumulator
    mov.f32 %sum, 0f00000000;                    // 0.0f

    // loop over K dimension, stride = blockDim.x (256)
LOOP_START:
    setp.ge.u32 %p, %tid, %K;
    @%p bra LOOP_END;                // if tid >= K, exit loop (handles K < blockDim)

    // col = tid + i*blockDim.x   (we will advance col inside loop)
    mov.u32 %col, %tid;

LOOP_ITER:
    // while (col < K)
    setp.ge.u32 %p, %col, %K;
    @%p bra LOOP_EXIT_ITER;

    // address of A[bid, col] = A + (row_offset + col) * sizeof(half)
    mad.wide.u32 %a_addr, %col, 2, %row_offset;   // 2 bytes per half
    add.u64 %a_addr, %A, %a_addr;

    // address of B[col] = B + col * sizeof(half)
    mul.wide.u32 %b_addr, %col, 2;
    add.u64 %b_addr, %B, %b_addr;

    // load fp16 values
    ld.global.nc.f16 %a_f16, [%a_addr];
    ld.global.nc.f16 %b_f16, [%b_addr];

    // convert to fp32
    cvt.f32.f16 %a_f32, %a_f16;
    cvt.f32.f16 %b_f32, %b_f16;

    // accumulate
    fma.rn.f32 %sum, %a_f32, %b_f32, %sum;

    // col += blockDim.x (256)
    add.u32 %col, %col, 256;
    bra LOOP_ITER;

LOOP_EXIT_ITER:
    // advance starting column for next block‑wide iteration
    // (handled by outer loop increment)
    // (nothing needed here)

LOOP_END:
    // ----------- reduction in shared memory ----------
    .shared .align 4 .b8 sdata[1024];   // 256 * 4 bytes (float)

    // store per‑thread sum into shared memory
    cvt.u32.u64 %a_addr, %tid;          // reuse %a_addr as index
    mul.wide.u32 %a_addr, %tid, 4;     // float occupies 4 bytes
    st.shared.u32 [sdata + %a_addr], %sum;

    bar.sync 0;                         // __syncthreads()

    // reduction tree (power‑of‑two blockDim.x = 256)
    .reg .u32 %offset;
    mov.u32 %offset, 128;
REDUCTION_LOOP:
    setp.eq.u32 %p, %offset, 0;
    @%p bra REDUCTION_DONE;

    setp.lt.u32 %p, %tid, %offset;
    @%p {
        // load partner value
        ld.shared.u32 %a_addr, [sdata + %tid*4];
        ld.shared.u32 %b_addr, [sdata + (%tid + %offset)*4];
        add.f32 %a_f32, %a_addr, %b_addr;
        st.shared.u32 [sdata + %tid*4], %a_f32;
    }
    bar.sync 0;
    shr.u32 %offset, %offset, 1;
    bra REDUCTION_LOOP;

REDUCTION_DONE:
    // thread 0 writes the final result
    setp.ne.u32 %p, %tid, 0;
    @%p bra DONE;

    // load reduced sum
    ld.shared.u32 %a_addr, [sdata];
    // convert to fp16
    cvt.rn.f16.f32 %a_f16, %a_addr;

    // store to C[bid]
    mul.wide.u32 %c_addr, %bid, 2;      // each output is half (2 bytes)
    add.u64 %c_addr, %C, %c_addr;
    st.global.f16 [%c_addr], %a_f16;

DONE:
    ret;
}
'''
