    def __init__(self):
        # Load the PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, A, B):
        """
        A: torch.Tensor of shape (M, K), dtype=torch.float16, device='cuda'
        B: torch.Tensor of shape (K, 1), dtype=torch.float16, device='cuda'
        Returns C: torch.Tensor of shape (M, 1), dtype=torch.float16, device='cuda'
        """
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        M, K = A.shape
        assert B.shape == (K, 1)

        C = torch.empty((M, 1), dtype=torch.float16, device='cuda')

        # launch configuration
        grid  = (M, )          # one block per output row
        block = (256, )        # 256 threads per block

        # arguments: pointers and dimensions
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            M,
            K
        ]

        # launch the kernel
        ptx_launch(self.module, "matvec_kernel", grid, block, args)

        return C
